INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','easy','flashcard','What is the time window for IV alteplase (tPA) administration in acute ischaemic stroke?','["Within 4.5 hours of symptom onset (or last known well time)"]','A','The 4.5-hour window applies to IV alteplase 0.9 mg/kg (max 90 mg); 10% given as bolus, remainder over 60 minutes. Earlier treatment yields better outcomes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','easy','flashcard','What blood pressure must be achieved before administering IV tPA in acute ischaemic stroke?','["BP must be <185/110 mmHg before and maintained <180/105 mmHg during and after thrombolysis"]','A','If BP is above threshold, carefully lower with IV labetalol or nicardipine before tPA. Uncontrolled hypertension increases haemorrhagic transformation risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','medium','flashcard','State three absolute contraindications to IV tPA in acute ischaemic stroke.','["(1) Prior intracranial haemorrhage; (2) Ischaemic stroke or serious head trauma within 3 months; (3) Active internal bleeding (excluding menses). Others: BP persistently >185/110, platelets <100,000, INR >1.7"]','A','Knowing contraindications is critical to safe thrombolysis. Each must be checked systematically before tPA is given.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','medium','flashcard','What does the NIHSS measure and what score range suggests eligibility for acute stroke treatment?','["NIHSS (0-42) quantifies neurological deficit across 15 items. NIHSS 4 or above generally warrants treatment; scores 6 or above support thrombectomy consideration"]','A','NIHSS assesses consciousness, gaze, visual fields, facial palsy, motor arm/leg, limb ataxia, sensory, language, dysarthria, and extinction. It guides triage and prognosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','medium','flashcard','What are the key eligibility criteria for mechanical thrombectomy in acute ischaemic stroke?','["(1) Large vessel occlusion (ICA, M1/M2, basilar); (2) NIHSS 6 or above; (3) Within 6 hours of onset (up to 24 hours with salvageable penumbra on imaging); (4) No large established infarct core (ASPECTS 6 or above)"]','A','Thrombectomy combined with IV tPA is superior to tPA alone for large vessel occlusion. CT perfusion or DWI/PWI mismatch can extend the treatment window to 24 hours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','easy','flashcard','When should aspirin be started after acute ischaemic stroke treated with IV tPA?','["Aspirin is withheld for 24 hours after tPA administration, then started at 300 mg (Ghana STG) or 160-325 mg (international guidelines)"]','A','Concurrent antiplatelet use with tPA increases bleeding risk. After a 24-hour CT to exclude haemorrhage, aspirin is safe to commence and reduces early recurrence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','medium','flashcard','What is the recommended blood pressure target in acute ischaemic stroke NOT treated with thrombolysis?','["Permit BP up to 220/120 mmHg in the first 24-48 hours unless end-organ damage is present; avoid aggressive lowering as it may extend ischaemia"]','A','Autoregulation is impaired in the ischaemic penumbra. Ghana STG advises a 20% reduction over 24 hours if BP exceeds 180/110 mmHg. Permissive hypertension maintains perfusion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','hard','flashcard','Name four components of secondary prevention following ischaemic stroke.','["(1) Antiplatelet therapy (aspirin plus or minus dipyridamole or clopidogrel); (2) Statin therapy (atorvastatin 40-80 mg); (3) Antihypertensive therapy; (4) Anticoagulation for cardioembolic source such as AF (warfarin or DOAC)"]','A','Dual antiplatelet (aspirin + clopidogrel) for 21 days may be used after minor stroke or TIA. Risk factor modification (diabetes, smoking, weight) is equally critical for long-term prevention.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','hard','flashcard','What imaging finding on CT is required before deciding between ischaemic and haemorrhagic stroke management?','["A non-contrast CT head must be performed urgently to exclude intracerebral haemorrhage before any antithrombotic or thrombolytic therapy is given"]','A','CT is the initial imaging of choice — it rapidly excludes haemorrhage. MRI-DWI is more sensitive for early ischaemia but takes longer. Never give tPA without ruling out haemorrhage on CT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','hard','flashcard','What is the ABCD2 score used for and what score indicates high short-term stroke risk after TIA?','["The ABCD2 score predicts short-term stroke risk after TIA. Score 4 or above out of 7 indicates high risk; score 6 or above indicates very high 2-day stroke risk of approximately 8%. Components: Age 60 or above (1), BP 140/90 or above (1), Clinical features (unilateral weakness 2, speech only 1), Duration 60 min or above (2) or 10-59 min (1), Diabetes (1)"]','A','TIA is a neurological emergency. High ABCD2 score warrants urgent investigation and same-day or 24-hour specialist review to prevent early stroke.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','easy','flashcard','What blood pressure target is recommended in acute spontaneous intracerebral haemorrhage (ICH)?','["Systolic BP should be lowered to below 140 mmHg within 1 hour and maintained for 7 days; this reduces haematoma expansion without increasing adverse events"]','A','Intensive BP lowering with IV labetalol or nicardipine is standard. Ghana STG advises avoiding sublingual nifedipine; gradual reduction is preferred.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','medium','flashcard','How is ICH due to warfarin (vitamin K antagonist) reversed?','["Prothrombin Complex Concentrate (PCC 4-factor: factors II, VII, IX, X) 25-50 units/kg IV plus Vitamin K 10 mg IV slow infusion. PCC acts within minutes; Vitamin K takes 6-12 hours to restore ongoing production"]','A','Fresh Frozen Plasma (FFP) is an alternative but requires large volumes and takes longer. PCC is preferred for rapid, reliable reversal. INR should be checked post-reversal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','medium','flashcard','What specific reversal agent is used for dabigatran-associated intracranial haemorrhage?','["Idarucizumab (Praxbind) 5 g IV given as two 2.5 g doses within 15 minutes — a humanised monoclonal antibody fragment that binds dabigatran with very high affinity"]','A','Idarucizumab provides complete, rapid reversal of dabigatran. For factor Xa inhibitors (rivaroxaban, apixaban), andexanet alfa is the specific reversal agent; PCC is an alternative.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','medium','flashcard','State the Hunt-Hess grading scale for subarachnoid haemorrhage (SAH).','["Grade I: Asymptomatic or mild headache; Grade II: Severe headache, nuchal rigidity, no deficit; Grade III: Drowsy, mild focal deficit; Grade IV: Stuporous, moderate-severe hemiparesis; Grade V: Deep coma, decerebrate posturing. Grades correlate with mortality (I low, V exceeds 80%)"]','A','Higher Hunt-Hess grade predicts worse surgical/interventional risk and overall prognosis. Grade I-II are usually surgical candidates; grade IV-V have high mortality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','easy','flashcard','What is the dose and duration of nimodipine in subarachnoid haemorrhage?','["Nimodipine 60 mg orally every 4 hours for 21 days (total duration)"]','A','Nimodipine is a calcium channel blocker that reduces cerebral vasospasm-related ischaemia after SAH. It improves neurological outcomes but does not reduce angiographic vasospasm. Must be given orally — IV form not licensed in most countries.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','medium','flashcard','What is the Fisher CT grade in SAH and which grade predicts the highest vasospasm risk?','["Fisher Grade 1: No blood; Grade 2: Diffuse thin SAH less than 1 mm; Grade 3: Focal clot or thick layer greater than 1 mm — HIGHEST risk of vasospasm; Grade 4: Intraventricular or intraparenchymal clot"]','A','Fisher Grade 3 (thick, localised subarachnoid clot) carries the highest risk of delayed cerebral ischaemia from vasospasm. The modified Fisher scale also accounts for intraventricular haemorrhage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','easy','flashcard','When does cerebral vasospasm typically occur after subarachnoid haemorrhage?','["Vasospasm typically occurs between day 4 and day 14 after SAH, peaking around day 7-10"]','A','Delayed cerebral ischaemia from vasospasm is a major cause of morbidity and mortality after SAH. Transcranial Doppler and CT angiography guide detection. Triple-H therapy or endovascular intervention may be needed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','hard','flashcard','What are the classic features of a sentinel bleed (warning leak) before major SAH?','["Sudden, severe thunderclap headache described as the worst headache of the patient life; may resolve within hours; may be accompanied by brief loss of consciousness or vomiting; CT may be normal and LP is required to detect xanthochromia"]','A','Sentinel bleeds occur in up to 50% of patients before major SAH. They are frequently dismissed as tension headache. CT sensitivity within 6 hours is above 98%; after 6 hours or if CT negative, LP is mandatory.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','hard','flashcard','What are the commonest causes of spontaneous intracerebral haemorrhage?','["(1) Hypertension — most common (50-70%), affecting deep structures (putamen, thalamus, pons, cerebellum); (2) Cerebral amyloid angiopathy — lobar haemorrhages in elderly; (3) Anticoagulant/thrombolytic therapy; (4) AVM/aneurysm rupture; (5) Venous sinus thrombosis"]','A','Location provides diagnostic clues: putamen/thalamus/pons/cerebellum = hypertensive; cortical/lobar = amyloid angiopathy or AVM. All patients need BP control and reversal of coagulopathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','hard','flashcard','What ECG changes are associated with subarachnoid haemorrhage and what is their significance?','["SAH causes neurogenic ECG changes: deeply inverted T-waves (cerebral T-waves), QTc prolongation, ST changes mimicking MI, U-waves, arrhythmias (AF, bradycardia). These are neurogenic — not primary cardiac — but indicate hypothalamic involvement and can cause troponin elevation"]','A','Neurogenic cardiac dysfunction (takotsubo/stress cardiomyopathy) can complicate SAH management. Continuous cardiac monitoring in ICU is essential. Do not withhold nimodipine unless severe haemodynamic compromise.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','easy','flashcard','What is the clinical distinction between a focal and a generalised seizure?','["Focal seizures originate in one hemisphere (may be aware or with impaired awareness); generalised seizures involve both hemispheres from onset (e.g. tonic-clonic, absence, myoclonic, atonic)"]','A','Focal seizures with secondary generalisation can mimic primary generalised seizures. EEG and clinical semiology (aura, automatisms, head/eye deviation) help distinguish them. Classification guides AED choice.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','easy','flashcard','What is the first-line AED for juvenile myoclonic epilepsy (JME)?','["Sodium valproate (valproic acid) is highly effective for JME; lamotrigine or levetiracetam are alternatives, especially in women of childbearing age due to valproate teratogenicity"]','A','JME features myoclonic jerks on waking, generalised tonic-clonic seizures, and sometimes absence. Carbamazepine and phenytoin are contraindicated as they worsen myoclonus.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','medium','flashcard','What is the first-line treatment for focal epilepsy in adults?','["Carbamazepine or lamotrigine are both first-line for focal onset seizures. Levetiracetam is also widely used due to its favourable side effect profile and lack of enzyme induction"]','A','Carbamazepine is an enzyme inducer and interacts with many drugs. Lamotrigine requires slow titration to avoid Stevens-Johnson syndrome. Levetiracetam can cause behavioural side effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','hard','flashcard','State the stepwise protocol for convulsive status epilepticus management.','["Step 1 (0-5 min): IV/IM/buccal benzodiazepine — lorazepam 4 mg IV, diazepam 10 mg IV, or midazolam 10 mg IM/buccal; Step 2 (5-30 min): IV fosphenytoin 20 mg PE/kg or levetiracetam 60 mg/kg or valproate 40 mg/kg; Step 3 (above 30-60 min, refractory): anaesthetic doses — thiopental, propofol, or midazolam infusion with EEG monitoring in ICU"]','A','Status epilepticus: seizure lasting more than 5 minutes or 2 or more seizures without recovery. Refractory SE (above 30 min) requires ICU admission and continuous EEG monitoring.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','medium','flashcard','What are the main indications for EEG in the evaluation of seizures?','["(1) Confirm epilepsy diagnosis and classify seizure type; (2) Identify epileptic syndrome; (3) Detect non-convulsive status epilepticus; (4) Monitor treatment response in SE; (5) Pre-surgical evaluation for refractory epilepsy; (6) Evaluate for encephalopathy"]','A','A normal EEG does not exclude epilepsy — interictal epileptiform discharges are present in only 50% of first EEGs. Sleep deprivation, hyperventilation, and photic stimulation are activation procedures.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','medium','flashcard','What driving restrictions are typically advised after a first unprovoked seizure?','["Patients must not drive until seizure-free for a defined period — typically 6 months after a first unprovoked seizure (varies by jurisdiction); in Ghana and many African countries, patients are advised not to drive until seizure-free for at least 1 year on treatment"]','A','Specific periods vary by country. Patients should be counselled explicitly, and this must be documented. Seizure recurrence risk is highest in the first year after first seizure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','easy','flashcard','What is the first-line AED for childhood absence epilepsy?','["Ethosuximide (first choice) or sodium valproate; lamotrigine is an alternative. Carbamazepine is contraindicated as it worsens absence seizures"]','A','Absence seizures are brief (under 30 sec), with abrupt onset/cessation, blank stare, and 3 Hz spike-and-wave on EEG. Ethosuximide has fewer cognitive side effects than valproate in children.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','medium','flashcard','What is the most important AED to avoid in pregnancy and why?','["Sodium valproate — associated with neural tube defects (1-2%), cardiac malformations, facial clefts, and valproate embryofetal syndrome; also linked to significant neurodevelopmental delay in exposed children. Avoid unless no other effective AED"]','A','All women with epilepsy on AEDs should take folic acid 5 mg/day pre-conception and throughout pregnancy. Lamotrigine and levetiracetam are among the safer options in pregnancy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','hard','flashcard','What clinical features distinguish Todd paresis from an acute stroke?','["Todd paresis: transient focal weakness following a seizure, lasting minutes to hours (rarely up to 48 hours), gradually resolving; occurs ipsilateral to seizure focus; preceded by witnessed seizure; no acute infarct on DWI MRI. Stroke: sudden onset without preceding seizure, persistent deficit, acute DWI lesion"]','A','Todd paresis can mimic stroke. Always ask about preceding seizure activity. Thrombolysis should not be given for Todd paresis — urgent MRI helps differentiate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','hard','flashcard','What are the common features of phenytoin toxicity and what is the therapeutic serum level?','["Therapeutic range: 10-20 mg/L (40-80 micromol/L). Toxicity: above 20 mg/L — nystagmus; above 30 mg/L — ataxia, dysarthria; above 40 mg/L — encephalopathy, seizures. Chronic effects: gingival hyperplasia, hirsutism, coarsening of facial features, peripheral neuropathy, osteoporosis"]','A','Phenytoin has non-linear (zero-order) kinetics — small dose changes cause large level changes. IV phenytoin must be given slowly (below 50 mg/min) to avoid cardiac arrhythmia. Fosphenytoin is safer IV.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','easy','flashcard','What does the mnemonic TRAP stand for in Parkinson disease?','["T — Tremor (resting, 4-6 Hz, pill-rolling); R — Rigidity (cogwheel/leadpipe); A — Akinesia/Bradykinesia (slowness of movement); P — Postural instability (loss of righting reflexes, falls)"]','A','At least two of the four cardinal features (especially bradykinesia plus one of tremor or rigidity) are required for diagnosis. Asymmetric onset is characteristic of idiopathic PD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','easy','flashcard','State the Hoehn-Yahr staging scale for Parkinson disease.','["Stage 1: Unilateral disease only; Stage 2: Bilateral, no balance impairment; Stage 3: Mild-moderate bilateral, some postural instability, physically independent; Stage 4: Severe disability, still able to walk/stand unassisted; Stage 5: Wheelchair-bound or bedridden unless aided"]','A','Hoehn-Yahr stages guide prognosis and intervention. DBS is typically considered in stage 3 or above with motor complications on levodopa. Stages 1-2 usually respond well to medical therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','medium','flashcard','What is the standard levodopa-to-carbidopa ratio in co-careldopa tablets?','["The standard ratio is 4:1. Standard formulations include co-careldopa 100/25 mg (levodopa 100 mg + carbidopa 25 mg). Carbidopa inhibits peripheral dopa decarboxylase, increasing CNS levodopa availability and reducing peripheral side effects (nausea, vomiting, hypotension)"]','A','At least 75 mg/day of carbidopa is needed to fully inhibit peripheral conversion. Levodopa remains the most effective PD treatment but long-term use leads to motor complications.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','medium','flashcard','What is the wearing-off phenomenon in Parkinson disease?','["Wearing-off (end-of-dose deterioration): return of PD symptoms before the next levodopa dose is due, as the duration of response shortens. Managed by increasing dose frequency, adding COMT inhibitors (entacapone), MAO-B inhibitors (selegiline/rasagiline), or dopamine agonists"]','A','Wearing-off typically develops 3-5 years after starting levodopa. Patients report predictable return of tremor, rigidity, and slowness before each dose. Motor diaries help identify the pattern.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','medium','flashcard','What is peak-dose dyskinesia in Parkinson disease and how is it managed?','["Peak-dose dyskinesia: involuntary writhing/choreiform movements occurring at peak levodopa plasma level (1-2 hours after dose). Managed by reducing individual levodopa dose (increasing frequency to maintain total daily dose), adding amantadine, or considering DBS"]','A','Dyskinesias are drug-induced, not a direct PD complication. They are often preferred by patients over the off state. Amantadine is the only drug proven to reduce peak-dose dyskinesia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','hard','flashcard','What are the indications for deep brain stimulation (DBS) in Parkinson disease?','["(1) Good levodopa response but disabling motor complications (dyskinesias, wearing-off); (2) Medically refractory tremor; (3) Hoehn-Yahr stage 2-3 or above with inadequate medical control; (4) No significant cognitive impairment; (5) Age typically below 70 years. STN or GPi are the main DBS targets"]','A','DBS does not improve features that do not respond to levodopa (falls, speech, autonomic). STN DBS allows levodopa dose reduction; GPi DBS is preferred when dyskinesia is the main problem.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','easy','flashcard','Name four non-motor features of Parkinson disease that may precede motor symptoms.','["(1) Hyposmia (loss of smell) — often earliest; (2) REM sleep behaviour disorder (RBD); (3) Constipation; (4) Depression/anxiety. Other prodromal features include excessive daytime sleepiness and urinary dysfunction"]','A','Non-motor symptoms often predate motor diagnosis by years (the prodromal phase). RBD — acting out dreams — is a particularly strong predictor of synucleinopathy (PD, Lewy body dementia, MSA).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','medium','flashcard','What is the pathological hallmark of Parkinson disease?','["Loss of dopaminergic neurons in the substantia nigra pars compacta, with intraneuronal Lewy bodies (eosinophilic cytoplasmic inclusions composed primarily of aggregated alpha-synuclein protein)"]','A','Symptoms emerge when approximately 50-70% of nigral neurons are lost. DaTscan (SPECT dopamine transporter imaging) can detect presynaptic dopaminergic deficit to support diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','hard','flashcard','What drugs should be avoided in Parkinson disease because they worsen parkinsonism?','["Dopamine antagonists: metoclopramide, prochlorperazine (avoid as antiemetics); antipsychotics (haloperidol, risperidone, olanzapine — use quetiapine or clozapine if needed); lithium; valproate; calcium channel blockers (flunarizine, cinnarizine). Abrupt levodopa withdrawal risks a neuroleptic malignant-like syndrome"]','A','Domperidone is the preferred antiemetic in PD as it does not cross the blood-brain barrier. Clozapine and quetiapine are safe antipsychotic alternatives in PD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','hard','flashcard','How does Parkinson disease dementia (PDD) differ from Dementia with Lewy Bodies (DLB)?','["Both share alpha-synuclein pathology and Lewy bodies. The 1-year rule distinguishes them: DLB — dementia onset within 1 year of parkinsonian motor features (or dementia first); PDD — dementia develops more than 1 year after established PD motor diagnosis. Both are synucleinopathies on a spectrum"]','A','Cholinesterase inhibitors (rivastigmine) are approved for PDD. Antipsychotics (except quetiapine/clozapine) are dangerous in both conditions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','easy','flashcard','What are the two hallmark histopathological features of Alzheimer disease?','["(1) Extracellular beta-amyloid (Abeta) senile plaques; (2) Intracellular neurofibrillary tangles (NFTs) composed of hyperphosphorylated tau protein"]','A','NFT burden correlates better with cognitive severity than plaque burden. The hippocampus and entorhinal cortex are affected early, explaining prominent episodic memory loss as the initial symptom.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','easy','flashcard','What is the clinical triad of Dementia with Lewy Bodies (DLB)?','["(1) Visual hallucinations (well-formed, recurrent); (2) Parkinsonism (bradykinesia, rigidity, rarely tremor); (3) Fluctuating cognition with pronounced variation in attention and alertness. REM sleep behaviour disorder is an additional core feature"]','A','Two core features are sufficient to diagnose probable DLB. Patients are exquisitely sensitive to neuroleptics — avoid antipsychotics. DaTscan shows reduced dopamine transporter uptake.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','medium','flashcard','Which lobes are predominantly affected in frontotemporal dementia (FTD) and what are its clinical variants?','["Frontal and temporal lobes. Three main variants: (1) Behavioural variant FTD (bvFTD) — disinhibition, apathy, hyperorality, perseveration; (2) Semantic variant PPA (svPPA) — loss of word meaning; (3) Non-fluent/agrammatic PPA — effortful, agrammatic speech"]','A','FTD is the most common dementia under 65 years. Memory is relatively preserved early (unlike Alzheimer disease). Associated with TDP-43 or tau pathology; 30-40% have a family history.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','medium','flashcard','What are the main modifiable vascular risk factors for vascular dementia?','["Hypertension (most important), diabetes mellitus, hyperlipidaemia, atrial fibrillation, smoking, obesity, physical inactivity, excessive alcohol. Treatment of these risk factors is the primary prevention and management strategy"]','A','Vascular dementia is the second most common dementia. It often presents as stepwise cognitive decline after strokes. No approved pharmacotherapy for VaD; management is risk factor control.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','easy','flashcard','What MMSE score ranges correspond to mild, moderate, and severe Alzheimer disease?','["Mild: MMSE 21-26; Moderate: MMSE 10-20; Severe: MMSE below 10. Normal: MMSE 27-30 (maximum score 30)"]','A','MMSE is a bedside cognitive screening tool. Score below 24 suggests cognitive impairment but must be interpreted with patient age and education. MoCA (cutoff below 26) is more sensitive for mild impairment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','medium','flashcard','What pharmacological treatments are approved for Alzheimer disease?','["(1) Cholinesterase inhibitors (donepezil, rivastigmine, galantamine) — for mild-moderate AD; (2) Memantine (NMDA receptor antagonist) — for moderate-severe AD; may be combined with cholinesterase inhibitor. Neither is curative; they provide modest symptomatic benefit"]','A','Side effects of cholinesterase inhibitors include nausea, diarrhoea, bradycardia. Memantine reduces glutamate excitotoxicity. Anti-amyloid biologics (lecanemab, donanemab) are emerging therapies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','hard','flashcard','What are the reversible (potentially treatable) causes of dementia that must be excluded?','["DEMENTIA mnemonic: Drugs; Emotional (depression — pseudodementia); Metabolic (hypothyroidism, B12/folate deficiency, uraemia, liver disease); Eyes/Ears; Normal pressure hydrocephalus; Tumour/trauma; Infections (syphilis, HIV, prion); Alcohol/Anaemia. Also: hypercalcaemia, adrenal disease"]','A','Reversible causes account for approximately 10-15% of dementia presentations. Basic workup includes FBC, TFTs, B12/folate, glucose, renal/liver function, syphilis serology, HIV, CT head.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','hard','flashcard','What is normal pressure hydrocephalus (NPH) and what is its clinical triad?','["NPH: communicating hydrocephalus with normal opening CSF pressure on LP. Clinical triad (Hakim-Adams): (1) Gait disturbance (magnetic gait — wide-based, shuffling, feet glued to floor); (2) Urinary incontinence; (3) Cognitive impairment (subcortical pattern). Triad appears in that order"]','A','NPH is potentially reversible with ventriculoperitoneal (VP) shunting. Gait improvement after large-volume LP (30-50 mL CSF removal) predicts surgical response.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','hard','flashcard','What are the features of Creutzfeldt-Jakob disease (CJD) that distinguish it from other dementias?','["CJD: rapidly progressive dementia over weeks-months; myoclonus; cerebellar ataxia; visual disturbances; akinetic mutism terminally. EEG: periodic sharp-wave complexes. MRI: diffusion restriction in cortex (cortical ribboning) and basal ganglia. CSF 14-3-3 protein elevated. Fatal within 12 months in 90%"]','A','CJD is a prion disease — always fatal. Sporadic CJD is most common. Variant CJD (vCJD) from BSE exposure affects younger patients with psychiatric prodrome and pulvinar sign on MRI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','medium','flashcard','What genetic mutation is most commonly associated with familial early-onset Alzheimer disease?','["Mutations in PSEN1 (presenilin-1, chromosome 14) are the most common cause of familial AD (autosomal dominant). Other mutations: PSEN2 (chromosome 1) and APP (chromosome 21). ApoE e4 allele is the major genetic risk factor for late-onset sporadic AD"]','A','Trisomy 21 (Down syndrome) individuals virtually all develop AD pathology by age 40 due to extra copy of APP gene. ApoE e4 increases risk but is not deterministic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','medium','flashcard','What are the two key principles of the McDonald 2017 criteria for MS diagnosis?','["Dissemination in Space (DIS): lesions in 2 or more of 4 CNS regions (periventricular, juxtacortical, infratentorial, spinal cord); AND Dissemination in Time (DIT): new T2 or gadolinium-enhancing lesions on follow-up MRI, or simultaneous asymptomatic enhancing and non-enhancing lesions"]','A','McDonald criteria allow MS diagnosis after a single clinical attack if MRI demonstrates both DIS and DIT. CSF oligoclonal bands can substitute for DIT in some criteria versions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','easy','flashcard','What is the treatment for an acute MS relapse?','["High-dose IV methylprednisolone 1 g/day for 3-5 days (or oral methylprednisolone 500 mg/day as equivalent). Steroids shorten relapse duration but do not alter long-term disability"]','A','Not all relapses require treatment — only those causing significant disability. Avoid treating pseudo-relapses (infection, fever, Uhthoff phenomenon) with steroids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','medium','flashcard','What is the Uhthoff phenomenon in multiple sclerosis?','["Temporary worsening of MS symptoms with heat or rise in body temperature (fever, exercise, hot bath). Caused by impaired conduction in demyelinated axons at higher temperatures. Symptoms resolve when temperature normalises — not a true relapse"]','A','Uhthoff phenomenon was historically used to diagnose MS before MRI. Patients should be warned to avoid heat and treat fevers promptly. It does not require steroids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','easy','flashcard','What are the typical features of optic neuritis in MS?','["Painful loss of vision (pain on eye movement), reduced colour vision (especially red), afferent pupillary defect (RAPD), central scotoma, and swollen optic disc if acute. Most recover vision. High risk of MS if MRI shows demyelinating lesions"]','A','Optic neuritis is a common presenting feature of MS (25%). Usually unilateral. Visual evoked potentials (VEPs) show prolonged P100 latency. MRI of brain/orbit confirms diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','hard','flashcard','Name three disease-modifying therapies (DMTs) for relapsing-remitting MS and their main risks.','["(1) Interferon-beta-1a/1b — injection-site reactions, flu-like symptoms, hepatotoxicity; (2) Natalizumab (anti-VLA-4) — risk of PML from JC virus, especially JC antibody positive plus prior immunosuppression; (3) Alemtuzumab (anti-CD52) — secondary autoimmunity (thyroid disease, ITP, nephropathy), infusion reactions"]','A','DMT choice is stratified by disease activity, side-effect profile, and patient preference. High-efficacy therapies (natalizumab, alemtuzumab, ocrelizumab) provide greater benefit in active disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','medium','flashcard','What CSF findings support a diagnosis of multiple sclerosis?','["Oligoclonal bands (OCBs) in CSF but not serum (present in above 90% of MS patients); mildly elevated IgG index; mildly elevated protein; lymphocytic pleocytosis (usually below 50 cells/uL). Markedly elevated cells suggest infection or NMOSD"]','A','OCBs in CSF but not in paired serum represent intrathecal IgG synthesis. Sensitive but not specific for MS (also in CNS infections, neurosarcoidosis). A normal LP does not exclude MS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','medium','flashcard','What is clinically isolated syndrome (CIS) and what predicts conversion to MS?','["CIS: first episode of demyelinating neurological symptoms lasting 24 hours or more, without fever or infection. Predictors of MS conversion: (1) 1 or more T2 lesion on brain MRI (80% risk); (2) CSF OCBs; (3) Multiple MRI lesions meeting DIS criteria. No MRI lesions = low conversion risk (approximately 20%)"]','A','After a CIS with high-risk MRI, starting a DMT reduces conversion to MS and delays second attack. Earlier treatment leads to better long-term disability outcomes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','hard','flashcard','How does neuromyelitis optica spectrum disorder (NMOSD) differ from MS on MRI and serology?','["NMOSD: longitudinally extensive transverse myelitis (3 or more vertebral segments on MRI); area postrema involvement (hiccups, nausea); optic neuritis often bilateral and severe; AQP4-IgG antibody positive in approximately 75% or MOG-IgG positive. MS: short cord lesions (below 2 segments); AQP4 negative; OCBs common"]','A','NMOSD attacks are more severe than MS relapses and recovery is often incomplete. MS DMTs (natalizumab, fingolimod, interferons) can worsen NMOSD — correct diagnosis is critical.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','hard','flashcard','What is progressive multifocal leukoencephalopathy (PML) and which MS drug most commonly causes it?','["PML is a demyelinating brain infection caused by JC virus reactivation. Natalizumab causes PML in approximately 1/10,000 patients; risk increases with JC antibody index above 1.5, more than 2 years of treatment, and prior immunosuppressant use. MRI shows non-enhancing white matter lesions; CSF JC virus PCR confirms diagnosis"]','A','PML risk stratification using JC antibody titres is mandatory before and during natalizumab therapy. If PML is suspected, stop natalizumab immediately and manage IRIS (immune reconstitution inflammatory syndrome).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','easy','flashcard','What is the most common presenting symptom of multiple sclerosis?','["Optic neuritis (painful visual loss, RAPD) and sensory symptoms (numbness, paraesthesia) are the most common initial presentations; limb weakness, diplopia, and ataxia are also frequent. Any symptom must last 24 hours or more and occur outside of fever/infection to count as a clinical attack"]','A','The classic presentation is a young woman (20-40 years) with relapsing-remitting neurological symptoms at different times and locations. Female to male ratio is approximately 3:1 for RRMS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','hard','flashcard','State the CSF findings that distinguish bacterial, viral, and tuberculous meningitis.','["Bacterial: turbid, protein above 1 g/L, glucose below 2.2 mmol/L (CSF:serum ratio below 0.4), WBC 1000-10000 (neutrophils), elevated pressure. Viral: clear, protein 0.5-1 g/L, glucose normal, WBC 10-500 (lymphocytes). Tuberculous: viscous/clear, protein 1-5 g/L, glucose very low, WBC 100-500 (lymphocytes), fibrin web, AFB positive"]','A','CSF glucose must always be compared to simultaneous serum glucose. India ink stain and cryptococcal antigen for fungal meningitis. Meningococcal meningitis may initially show lymphocytic predominance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','medium','flashcard','What is the empiric antibiotic regimen for bacterial meningitis in adults aged 18-50 years?','["Ceftriaxone 2 g IV every 12 hours (or cefotaxime 2 g IV every 6 hours) plus dexamethasone 0.15 mg/kg IV every 6 hours for 4 days. Add ampicillin 2 g IV every 4 hours if Listeria is suspected (immunocompromised, age above 50, pregnancy)"]','A','Cover Streptococcus pneumoniae and Neisseria meningitidis in adults. In neonates, add ampicillin and gentamicin for Group B Strep and Listeria. Vancomycin added in areas with high penicillin-resistant pneumococcus.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','easy','flashcard','When should dexamethasone be given relative to antibiotics in bacterial meningitis?','["Dexamethasone should be given BEFORE or WITH the FIRST dose of antibiotics — given 15-20 minutes before or simultaneously. Do NOT give after antibiotics have already been started, as the anti-inflammatory benefit is lost"]','A','Dexamethasone 0.15 mg/kg QID for 4 days reduces cytokine release and lowers mortality and neurological complications, especially hearing loss in H. influenzae and S. pneumoniae meningitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','medium','flashcard','What are the contraindications to performing an LP in suspected meningitis?','["(1) Signs of raised ICP: papilloedema, focal neurological signs, GCS below 14, new-onset seizures; (2) Cardiovascular instability/septic shock; (3) Coagulopathy (platelets below 50,000 or INR above 1.5); (4) Overlying skin infection at LP site; (5) Suspected spinal cord compression. Always give antibiotics before CT — never delay treatment for imaging"]','A','LP should NEVER delay antibiotic treatment in suspected bacterial meningitis. Give antibiotics immediately, then CT if needed, then LP if safe.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','easy','flashcard','What is the dose of acyclovir for HSV encephalitis?','["Acyclovir 10 mg/kg IV every 8 hours for 14-21 days (21 days recommended for confirmed HSV encephalitis to minimise relapse risk)"]','A','HSV encephalitis affects the temporal lobes — presenting with fever, confusion, temporal lobe seizures, and personality change. MRI shows T2 hyperintensity in temporal lobes. Start acyclovir empirically without waiting for PCR result.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','medium','flashcard','What are the classical features of meningococcal septicaemia?','["Non-blanching petechial/purpuric rash, fever, hypotension, tachycardia, altered consciousness, meningism (neck stiffness, photophobia, Kernig sign, Brudzinski sign), DIC. The rash does not blanch under glass. This is a medical emergency — give benzylpenicillin immediately"]','A','Glass test — press a clear glass against the rash; if it does not blanch, suspect meningococcal disease. Give IV/IM benzylpenicillin immediately even in primary care before transfer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','hard','flashcard','What are the common causes of encephalitis and how is autoimmune encephalitis distinguished from infectious encephalitis?','["Infectious: HSV-1 (most common), VZV, EBV, CMV, enteroviruses, West Nile virus, TB, malaria. Autoimmune: anti-NMDA receptor encephalitis (young women, ovarian teratoma, psychiatric prodrome, seizures), LGI1, CASPR2. Key: autoimmune — antibody-positive, responds to immunotherapy; infectious — CSF PCR positive"]','A','Anti-NMDA receptor encephalitis is now more common than viral encephalitis in young patients. Screen for ovarian teratoma. Treatment: steroids, IVIG, plasmapheresis, rituximab.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','hard','flashcard','What is cryptococcal meningitis and how is it diagnosed and treated?','["Cryptococcus neoformans meningitis — seen in HIV/AIDS (CD4 below 100), organ transplant recipients. CSF: India ink stain positive, cryptococcal antigen (CrAg) titre elevated, low glucose, raised protein, lymphocytic pleocytosis. Treatment: induction — amphotericin B plus flucytosine for 2 weeks; consolidation — fluconazole 400 mg/day for 8 weeks; maintenance — fluconazole 200 mg/day"]','A','Cryptococcal meningitis is a major cause of death in HIV patients in sub-Saharan Africa. Raised ICP is a key complication — manage with serial LP or lumbar drain.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','medium','flashcard','What are the neurological complications of untreated bacterial meningitis?','["Hearing loss (most common, due to cochlear/VIII nerve damage), hydrocephalus, brain abscess, cerebral venous sinus thrombosis, cerebral infarction, cranial nerve palsies (III, VI, VII), seizures, intellectual impairment, subdural empyema"]','A','Hearing loss affects up to 30% of bacterial meningitis survivors, especially with S. pneumoniae and H. influenzae. Dexamethasone reduces hearing loss. Audiological assessment should be arranged at discharge.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','easy','flashcard','What are the three components of the classic meningitis triad?','["(1) Fever; (2) Neck stiffness (nuchal rigidity); (3) Photophobia/headache. All three are present in only approximately 44% of bacterial meningitis cases — absence of any one does not exclude the diagnosis"]','A','Additional signs: Kernig sign (inability to extend knee with hip flexed), Brudzinski sign (involuntary knee flexion when neck is flexed). Jolt accentuation of headache (worsening with rapid horizontal head rotation) is also a sensitive sign.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','easy','flashcard','What does the POUND mnemonic describe in migraine diagnosis?','["P — Pulsating quality; O — duration One day (4-72 hours); U — Unilateral location; N — Nausea/vomiting; D — Disabling (moderate-severe intensity). 4 or more of 5 features: sensitivity 91%, specificity 74% for migraine diagnosis"]','A','POUND provides a quick bedside screen for migraine. IHS ICHD-3 requires at least 5 attacks with at least 2 of 4 pain characteristics and 1 associated symptom (nausea/vomiting OR photophobia AND phonophobia).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','medium','flashcard','What is the mechanism of action of triptans in migraine?','["Triptans are selective 5-HT1B/1D receptor agonists. They cause: (1) Vasoconstriction of dilated cranial blood vessels (5-HT1B); (2) Inhibition of trigeminal nerve terminal neuropeptide release (5-HT1D); (3) Inhibition of pain transmission in the trigeminal nucleus caudalis (5-HT1D)"]','A','Triptans are contraindicated in ischaemic heart disease, stroke, uncontrolled hypertension, Prinzmetal angina, and basilar/hemiplegic migraine. Sumatriptan 50-100 mg orally or 6 mg SC is the prototype.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','medium','flashcard','Name four options for migraine prophylaxis and their key considerations.','["(1) Propranolol 40-120 mg/day — avoid in asthma, depression; (2) Topiramate 25-100 mg/day — teratogenic, cognitive slowing, weight loss; (3) Amitriptyline 10-75 mg/day — useful if comorbid depression/insomnia; (4) Valproate 400-1000 mg/day — avoid in women of childbearing age. Also: CGRP monoclonal antibodies (erenumab, fremanezumab) — newer, highly effective"]','A','Prophylaxis is indicated if migraines occur 4 or more days/month or significantly impair quality of life. Treatment should be trialled for at least 3 months before concluding lack of efficacy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','easy','flashcard','What are the characteristic features of cluster headache?','["Severe unilateral orbital/periorbital pain lasting 15-180 minutes, occurring in clusters (1-8 attacks/day for weeks-months). Ipsilateral autonomic features: lacrimation, nasal congestion, rhinorrhoea, ptosis, miosis, conjunctival injection. Male predominance (5:1). Nocturnal attacks common. Alcohol triggers attacks during active cluster"]','A','Cluster headache is the most severe primary headache. Acute treatment: high-flow 100% oxygen (12-15 L/min) and subcutaneous sumatriptan. Prophylaxis: verapamil (drug of choice), short courses of prednisolone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','medium','flashcard','What does the SNOOP4 mnemonic help identify in headache assessment?','["S — Systemic illness (fever, weight loss, cancer); N — Neurological deficit; O — Onset sudden (thunderclap); O — Older age (onset above 50 years); P — Progression/change in pattern; P — Postural component; P — Papilloedema; P — Precipitated by Valsalva/exercise"]','A','Any SNOOP4 red flag mandates urgent investigation (CT or MRI head). These features suggest secondary life-threatening headache causes such as SAH, meningitis, raised ICP, or malignancy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','hard','flashcard','What is medication overuse headache (MOH) and how is it managed?','["MOH develops when acute headache medications are used on 10 or more days/month for triptans/ergotamines/opioids, or 15 or more days/month for simple analgesics, for more than 3 months. Management: withdrawal of overused medication, bridging therapy (prednisolone taper), start prophylaxis, patient education"]','A','NSAIDs and paracetamol MOH threshold is 15 days/month. Opioid and triptan MOH threshold is 10 days/month. Withdrawal headache may worsen for 1-2 weeks. Multidisciplinary support improves success rates.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','easy','flashcard','What distinguishes a tension-type headache from migraine clinically?','["Tension-type: bilateral, pressing/tightening quality (band around head), mild-moderate severity, not aggravated by routine physical activity, no nausea/vomiting, no more than one of photophobia/phonophobia. Migraine: unilateral, pulsating, moderate-severe, worsened by activity, with nausea/vomiting and/or photophobia AND phonophobia"]','A','Tension-type headache is the most common headache (prevalence approximately 69%). Simple analgesics (paracetamol, NSAIDs) are first-line treatment. Amitriptyline is the most evidence-based prophylaxis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','hard','flashcard','What is idiopathic intracranial hypertension (IIH) and what is its treatment?','["IIH (pseudotumour cerebri): raised ICP without mass lesion or hydrocephalus. Occurs predominantly in obese women of childbearing age. Features: daily headache, pulsatile tinnitus, visual obscurations, papilloedema, sixth nerve palsy. LP opening pressure above 25 cmH2O. Treatment: weight loss (most important), acetazolamide 500-2000 mg/day, topiramate; optic nerve sheath fenestration or VP shunt for vision-threatening cases"]','A','Visual field testing is essential — IIH can cause permanent visual loss. Steroids not routinely recommended. Avoid tetracyclines (they trigger IIH). Regular fundoscopy to monitor papilloedema.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','medium','flashcard','What is a migraine aura and what are its typical features?','["Aura: reversible focal neurological symptoms preceding or accompanying migraine headache, lasting 5-60 minutes each. Most common: visual aura (positive — scintillating scotoma/fortification spectra; or negative — scotoma). Others: sensory (pins and needles), speech disturbance, motor (hemiplegic migraine — rare). Must spread gradually and fully resolve"]','A','Aura occurs in approximately 25-30% of migraineurs. Visual aura (fortification spectra or teichopsia) is classic. Aura with migraine increases ischaemic stroke risk, especially with combined oral contraceptive pill and smoking.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','hard','flashcard','What is the acute treatment of status migrainosus?','["Status migrainosus: migraine lasting more than 72 hours despite treatment. Management: IV fluids, IV metoclopramide 10 mg plus IV prochlorperazine, IV dexamethasone 8 mg (reduces recurrence), IV ketorolac, IV dihydroergotamine (DHE). IV magnesium sulphate has evidence for migraine with aura. Opioids should be avoided"]','A','Antiemetics (metoclopramide, prochlorperazine) treat both nausea and pain in status migrainosus. Dexamethasone reduces recurrence rate by approximately 26%. Opioids worsen medication overuse headache risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','easy','flashcard','What is albuminocytological dissociation in CSF and in which condition is it the hallmark finding?','["Albuminocytological dissociation: markedly elevated CSF protein (above 0.45 g/L, often above 1-2 g/L) with normal or near-normal white cell count (below 10 cells/uL). Hallmark of Guillain-Barré syndrome (GBS). Also seen in spinal cord compression and some tumours"]','A','The dissociation peaks 2-4 weeks after GBS onset and is present in approximately 80% of cases by week 2. It reflects albumin leakage from inflamed nerve roots without cellular infiltration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','medium','flashcard','What are the two evidence-based treatments for Guillain-Barré syndrome and their dosing?','["(1) IVIG: 0.4 g/kg/day IV for 5 days (total 2 g/kg); (2) Plasma exchange (plasmapheresis): 5 sessions over 2 weeks (250 mL/kg total). Both are equally effective; combination is NOT superior. Corticosteroids are NOT beneficial and may worsen outcome"]','A','Treatment is indicated for non-ambulatory GBS or rapidly worsening disease. IVIG is preferred in most centres for ease of administration. Begin treatment within 2-4 weeks of symptom onset.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','medium','flashcard','What autonomic complications of GBS require monitoring in ICU?','["Cardiac arrhythmias (bradycardia, tachycardia, heart block, asystole — most life-threatening), labile blood pressure (hypertension/hypotension), urinary retention, ileus, hyperhidrosis. All GBS patients with autonomic involvement need continuous cardiac monitoring"]','A','Autonomic dysfunction occurs in approximately 70% of GBS patients. Sudden cardiac arrest can occur. Vasopressors should be used cautiously in autonomic hypertension (paroxysmal, self-resolving).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','easy','flashcard','What is the clinical triad of Miller Fisher syndrome (MFS)?','["(1) Ophthalmoplegia (bilateral external ophthalmoplegia — ptosis and ophthalmoparesis); (2) Ataxia (cerebellar-type gait and limb ataxia); (3) Areflexia (absent deep tendon reflexes). GQ1b antibody is positive in above 90% of MFS cases"]','A','MFS is a GBS variant with descending pattern. Most patients recover fully without treatment, though IVIG or plasma exchange are used in severe cases. Anti-GQ1b antibodies also seen in Bickerstaff brainstem encephalitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','medium','flashcard','What are the most common preceding infections before Guillain-Barré syndrome?','["Campylobacter jejuni (most common, approximately 30% of GBS) — associated with axonal GBS subtypes (AMAN, AMSAN); Cytomegalovirus (CMV); Epstein-Barr virus (EBV); Mycoplasma pneumoniae; Zika virus; SARS-CoV-2. GBS follows infection by 2-4 weeks via molecular mimicry triggering anti-ganglioside antibodies"]','A','Campylobacter-associated GBS tends to be more severe and axonal, with slower and often incomplete recovery. AIDP (acute inflammatory demyelinating polyradiculoneuropathy) is the most common subtype in Western countries.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','easy','flashcard','What respiratory parameter is monitored to determine need for ventilatory support in GBS?','["Forced Vital Capacity (FVC) — intubation/ventilation is indicated when FVC falls below 15-20 mL/kg, or below 1 litre in an average adult. The 20-30-40 rule: MIP above -30 cmH2O, MEP below 40 cmH2O, or FVC below 20 mL/kg — any one criterion = consider intubation"]','A','GBS causes ascending paralysis that can reach respiratory muscles. Respiratory failure is the primary cause of death. Regular FVC monitoring (every 4-6 hours in progressive disease) is essential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','hard','flashcard','What are the causes of a symmetrical peripheral neuropathy with predominantly motor deficit?','["GBS (ascending, acute), chronic inflammatory demyelinating polyneuropathy (CIDP — chronic version of GBS, responds to steroids), multifocal motor neuropathy (MMN, asymmetric, anti-GM1 antibodies), lead toxicity, diphtheria, porphyria, hereditary motor neuropathy (Charcot-Marie-Tooth)"]','A','GBS progresses to nadir within 4 weeks; CIDP progresses above 8 weeks or relapses. CIDP responds to steroids (unlike GBS). Anti-GM1 antibodies suggest AMAN or MMN.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','medium','flashcard','What are the most common causes of a length-dependent sensorimotor peripheral neuropathy?','["(1) Diabetes mellitus (most common worldwide); (2) Alcohol-related neuropathy; (3) B12 deficiency; (4) Chronic kidney disease (uraemic neuropathy); (5) Hypothyroidism; (6) Drugs (vincristine, isoniazid, metronidazole, amiodarone, thalidomide); (7) Hereditary (Charcot-Marie-Tooth disease)"]','A','Length-dependent neuropathy: symptoms begin in feet (stocking-glove distribution). Nerve conduction studies differentiate axonal (reduced amplitude) from demyelinating (slowed velocity) patterns.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','hard','flashcard','How does diabetic peripheral neuropathy lead to foot complications and what is the prevention strategy?','["Sensory loss leads to undetected trauma, ulceration, infection, osteomyelitis, and amputation. Motor involvement causes claw toes and pressure points. Autonomic neuropathy causes dry skin and fissures. Prevention: tight glycaemic control, daily foot inspection, specialist footwear, neuropathic pain treatment (gabapentin, duloxetine, amitriptyline, pregabalin), prompt wound management"]','A','Diabetic foot is the leading cause of non-traumatic lower limb amputation globally. The at-risk foot requires multidisciplinary care (podiatry, vascular surgery, diabetology). Screen annually with 10-g monofilament.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','hard','flashcard','What is the Brighton Collaboration diagnostic criteria for Guillain-Barré syndrome?','["Brighton Level 1 (highest certainty): (1) Bilateral flaccid limb weakness; (2) Decreased/absent reflexes in weak limbs; (3) Monophasic course — nadir 12 hours to 28 days then plateau; (4) CSF: elevated protein, normal WBC (below 50 cells); (5) Electrophysiology consistent with GBS. Level 2: criteria 1-3 plus CSF OR electrophysiology. Level 3: clinical criteria 1-3 only"]','A','Brighton criteria standardise GBS case reporting for vaccine safety surveillance. Clinical criteria 1-3 (weakness, areflexia, monophasic course) form the diagnostic core at all levels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','easy','flashcard','What are the two main antibody types in myasthenia gravis and what do they target?','["(1) Anti-AChR (acetylcholine receptor) antibodies — present in 85% of generalised MG; (2) Anti-MuSK (muscle-specific tyrosine kinase) antibodies — present in approximately 40% of AChR-seronegative MG. AChR antibodies bind and block/destroy nicotinic AChR at the NMJ"]','A','MuSK-MG more commonly affects bulbar muscles, has prominent neck/respiratory weakness, and does not respond as well to pyridostigmine. Thymectomy benefits are mainly in AChR-positive MG.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','medium','flashcard','What is the Tensilon test (edrophonium test) and how is it performed?','["Edrophonium (Tensilon) is a short-acting acetylcholinesterase inhibitor. Procedure: give 2 mg IV test dose (watch 1 minute); if no adverse effects, give remaining 8 mg IV (total 10 mg). Positive result: brief improvement in ptosis or diplopia within 30-60 seconds. Have atropine ready for side effects (bradycardia, bronchospasm, hypersalivation)"]','A','The Tensilon test is largely replaced by antibody testing and ice pack test. It requires ECG monitoring and resuscitation facilities. False positives occur in motor neurone disease and brainstem lesions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','medium','flashcard','What are the indications for thymectomy in myasthenia gravis?','["(1) All patients with thymoma regardless of MG severity; (2) Generalised AChR antibody-positive MG in patients aged below 60 years; (3) Refractory MG not responding to immunosuppression. Extended transsternal thymectomy is preferred. Benefits may take 2-5 years to manifest"]','A','CT chest is mandatory in all MG patients to identify thymoma. Thymoma is present in 10-15% of MG patients. Thymectomy should be considered early in generalised AChR-positive MG.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','hard','flashcard','How is myasthenic crisis managed?','["(1) Admit to ICU, monitor FVC, consider intubation if FVC below 15-20 mL/kg or rapid deterioration; (2) Stop or reduce pyridostigmine (may worsen cholinergic secretions); (3) IVIG 2 g/kg over 5 days OR plasma exchange 5 sessions; (4) Continue/restart immunosuppression; (5) Identify and treat precipitant (infection, medications, surgery)"]','A','Crisis precipitants: infection (most common), aminoglycosides, fluoroquinolones, magnesium, beta-blockers, neuromuscular blocking agents. IV methylprednisolone can transiently worsen MG — use with caution.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','easy','flashcard','What are the clinical differences between myasthenia gravis and Lambert-Eaton myasthenic syndrome (LEMS)?','["MG: weakness worsens with repeated activity (fatigability), predominantly ocular/bulbar features, anti-AChR antibodies, normal reflexes. LEMS: proximal limb weakness improves briefly with exercise (facilitation), autonomic features (dry mouth), depressed reflexes that increase after exercise, anti-VGCC antibodies, associated with small cell lung cancer in 60%"]','A','Key distinction: MG — decremental response on repetitive nerve stimulation; LEMS — incremental response at high frequency. LEMS is paraneoplastic in most cases — screen for lung cancer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','medium','flashcard','What is the mechanism of action of pyridostigmine in myasthenia gravis?','["Pyridostigmine is an acetylcholinesterase inhibitor — it inhibits the enzyme that breaks down acetylcholine at the NMJ, increasing ACh concentration and duration of action in the synaptic cleft, thereby overcoming the reduced number of functional AChRs. It provides symptomatic relief but does not modify the underlying autoimmune disease"]','A','Standard dose: pyridostigmine 30-60 mg 3-5 times daily. Muscarinic side effects: diarrhoea, abdominal cramps, increased salivation, bradycardia. Glycopyrrolate can mitigate GI side effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','hard','flashcard','What drugs should be avoided in myasthenia gravis as they can precipitate or worsen weakness?','["Antibiotics: aminoglycosides (gentamicin, streptomycin), fluoroquinolones, azithromycin; Cardiovascular: beta-blockers, quinidine, procainamide, verapamil; Neurological: phenytoin, lithium; IV magnesium sulfate; non-depolarising neuromuscular blocking agents; Chloroquine/hydroxychloroquine at high dose"]','A','Always check drug interactions in MG patients. Penicillins, cephalosporins, and macrolides (other than azithromycin) are generally safe alternatives.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','medium','flashcard','What is the difference between myasthenic crisis and cholinergic crisis?','["Myasthenic crisis: insufficient ACh at NMJ — weakness, dyspnoea, dysphagia, ptosis; pupils may be dilated. Cholinergic crisis (excess pyridostigmine): SLUDGE — Salivation, Lacrimation, Urination, Defecation, GI cramps, Emesis — plus miosis, bradycardia, bronchospasm, fasciculations. Edrophonium test: improves myasthenic crisis; worsens or no change in cholinergic crisis"]','A','In cholinergic crisis, withhold anticholinesterases and give atropine. In myasthenic crisis, plasma exchange or IVIG is needed. Both may require mechanical ventilation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','hard','flashcard','What is ocular myasthenia gravis and what is its natural history?','["Ocular MG: weakness confined to extraocular muscles and eyelid levators only — presenting as ptosis (often asymmetric, worsens with sustained upgaze) and/or diplopia. AChR antibody positive in only 50%. Approximately 50-60% develop generalised MG within 2 years if untreated"]','A','Pyridostigmine and immunosuppression (prednisolone plus or minus azathioprine) reduce risk of generalisation. Thymectomy is less clearly beneficial in purely ocular MG. MRI orbit may be needed to exclude ocular nerve palsy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','easy','flashcard','What is the characteristic finding on repetitive nerve stimulation (RNS) in myasthenia gravis?','["Decremental response on low-frequency (3 Hz) repetitive nerve stimulation — amplitude of compound muscle action potential (CMAP) decreases by above 10% from the 1st to 4th or 5th stimulus. Reflects progressive NMJ transmission failure with depletion of immediately available ACh quanta"]','A','RNS is positive in approximately 75% of generalised MG but only 50% of ocular MG. Single-fibre EMG (SFEMG) is more sensitive (95%) and shows increased jitter. SFEMG is the most sensitive test for NMJ disorders.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','hard','flashcard','What are the immediate management steps for acute spinal cord compression?','["(1) Dexamethasone 8-16 mg IV stat (reduces cord oedema); (2) Urgent MRI whole spine (imaging of choice); (3) Emergency neurosurgical/spinal referral; (4) Urgent radiotherapy if malignant compression and not surgical candidate; (5) Catheterise bladder; (6) Manage pain; (7) DVT prophylaxis"]','A','Spinal cord compression from metastatic malignancy is the most common cause. The window for preserving neurological function is hours — time is spine. MRI defines level, extent, and cause.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','easy','flashcard','What are the red flag symptoms of cauda equina syndrome?','["(1) Saddle anaesthesia (numbness in perianal/perineal/inner thigh region); (2) Urinary retention — most important (overflow incontinence may occur); (3) Faecal incontinence; (4) Bilateral leg weakness/pain; (5) Loss of anal tone on rectal examination. Surgical emergency — requires immediate MRI and decompression"]','A','Cauda equina syndrome is most commonly caused by large central disc herniation at L4/5 or L5/S1. Any suspicion mandates same-day MRI. Delay in surgery beyond 24-48 hours worsens urinary/bowel recovery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','medium','flashcard','What are the clinical features of Brown-Sequard syndrome?','["Hemisection of the spinal cord. Ipsilateral: (1) Upper motor neurone weakness below lesion (corticospinal tract); (2) Loss of proprioception and vibration below lesion (dorsal columns). Contralateral: pain and temperature loss below lesion (spinothalamic tract — crosses 1-2 levels above entry)"]','A','Mnemonic: IPSILATERAL — motor weakness plus proprioception loss; CONTRALATERAL — pain and temperature loss. Causes: penetrating trauma (knife/gunshot wound), demyelination, tumour, cord haemorrhage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','medium','flashcard','What is anterior cord syndrome and what causes it?','["Anterior cord syndrome: infarction of the anterior 2/3 of the spinal cord (anterior spinal artery territory). Features: bilateral motor loss and bilateral pain/temperature loss below lesion; preserved proprioception, vibration, and light touch (posterior columns). Causes: aortic surgery, hyperflexion injury, anterior disc herniation, anterior spinal artery thrombosis"]','A','The anterior spinal artery supplies anterior grey horns and corticospinal/spinothalamic tracts. Anterior cord syndrome has the worst prognosis of the incomplete cord syndromes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','medium','flashcard','What is transverse myelitis and how is it treated?','["Transverse myelitis (TM): acute/subacute inflammatory demyelination of the spinal cord causing bilateral motor weakness, sensory level, and autonomic dysfunction (bladder/bowel). Causes: MS, NMOSD, post-infectious, sarcoidosis, SLE, idiopathic. MRI: T2 hyperintensity in cord. Treatment: IV methylprednisolone 1 g/day for 3-5 days; plasma exchange for severe steroid-refractory TM"]','A','AQP4-IgG and MOG-IgG testing is essential — NMOSD-associated TM is more severe (longitudinally extensive 3 or more segments). NMOSD-specific immunotherapy prevents relapses.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','easy','flashcard','What is the clinical triad of syringomyelia and what is its most common cause?','["Syringomyelia triad (cape distribution): (1) Bilateral loss of pain and temperature over shoulders, arms, and upper chest; (2) Preserved light touch and proprioception (dissociated sensory loss); (3) Lower motor neurone weakness/wasting of hands and arms. Most common cause: Chiari I malformation. Also: post-traumatic, post-meningitic, tumour-associated"]','A','Syrinx = fluid-filled cavity in the central cord. Expanding syrinx damages crossing spinothalamic fibres first (pain/temperature loss), then anterior horns (LMN weakness), then corticospinal tracts.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','hard','flashcard','What are the long-term complications of spinal cord injury and their management?','["(1) Pressure ulcers — regular turning every 2 hours, pressure-relieving mattress; (2) Spasticity — baclofen, physiotherapy; (3) Neurogenic bladder — intermittent self-catheterisation, anticholinergics; (4) Autonomic dysreflexia (above T6 injury) — BP spikes, remove trigger, sit patient up, IV labetalol/hydralazine; (5) DVT — LMWH; (6) Depression — antidepressants, psychological support"]','A','Autonomic dysreflexia is a medical emergency unique to high cervical/thoracic cord injuries. It can cause hypertensive crisis, stroke, or cardiac arrest. The most common trigger is bladder distension.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','hard','flashcard','How do upper motor neurone (UMN) and lower motor neurone (LMN) lesions differ clinically?','["UMN: weakness, increased tone (spasticity), hyperreflexia, Babinski positive, no early wasting, clonus. LMN: weakness, decreased tone (flaccidity), hyporeflexia or areflexia, Babinski absent/flexor, prominent muscle wasting, fasciculations. UMN lesion = above anterior horn cell; LMN = at or below anterior horn cell"]','A','The UMN/LMN distinction is foundational to neurological localisation. A combination of UMN and LMN signs at the same spinal level suggests ALS/MND.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','medium','flashcard','What is subacute combined degeneration of the spinal cord and what causes it?','["Subacute combined degeneration (SCD): B12 deficiency causing demyelination of the dorsal columns (loss of proprioception, vibration), corticospinal tracts (spastic weakness, hyperreflexia), and spinocerebellar tracts. Causes: pernicious anaemia (anti-intrinsic factor antibodies), strict veganism, gastrectomy, terminal ileal disease (Crohn disease), nitrous oxide anaesthesia"]','A','Serum B12 below 200 pg/mL is diagnostic; MRI spine shows dorsal column T2 hyperintensity. Treat with IM hydroxocobalamin 1 mg every 2-3 days for 2 weeks, then monthly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','hard','flashcard','What are the most important malignancies that cause metastatic spinal cord compression and at which spinal levels?','["Most common primaries: lung (most common overall), breast, prostate, renal cell carcinoma, lymphoma, myeloma. Distribution: thoracic spine (70%), lumbosacral (20%), cervical (10%). Mechanism: haematogenous spread to vertebral body then epidural extension causing cord compression. MRI whole spine essential as multiple levels compressed in 10-40% of cases"]','A','Pain is the earliest symptom — typically worse lying flat (unlike mechanical back pain). Weakness follows in days-weeks. Bladder dysfunction is a late sign. Pre-treatment ambulation is the strongest predictor of outcome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
